def solution(n: int) -> int:
    # Find previous lucky year (<= n) with at most one non-zero digit
    # If n itself is lucky, we need strictly previous (< n).
    def is_lucky(x: int) -> bool:
        cnt = 0
        while x:
            if x % 10 != 0:
                cnt += 1
                if cnt > 1:
                    return False
            x //=10
        return True

    # If n is lucky, adjust to n-1
    if is_lucky(n):
        n -= 1

    # Now need maximum lucky year <= n
    best = 0
    # Lucky numbers are d * 10^k where d in [1..9], k>=0
    # Given n <= 1e9, k up to 9 is safe
    for d in range(1, 10):
        p = 1
        for _ in range(10):
            val = d * p
            if val <= n and val > best:
                best = val
            p *= 10

    return n + (1 if is_lucky(n + 1) else 0) - best  # adjust since we might decremented n

